 if(e.species==='tulip'){for(let j=0;j<3;j++){const x=(j-1)*7*open;c.beginPath();c.moveTo(x-8,-17*open);c.bezierCurveTo(x-13,5,x-4,16,0,16);c.bezierCurveTo(x+13,7,x+11,-8,x+7,-20*open);c.quadraticCurveTo(x,-7,x-8,-17*open);c.fillStyle=pigment(c,n,P,x,0,17);c.fill();if(level>0)curve(c,[0,14],[x,-1],[x,-15*open],tint(P,-.22),.6)}}
 else if(e.species==='lavender'){for(let i=0;i<(level===0?7:11);i++){const y=12-i*4.5;for(const sign of [-1,1])ellipse(c,sign*(3+Math.sin(i)*1.4),y,4.2-i*.18,3,pigment(c,n,col(e,1+i%2),0,y,8),sign*.6)}}
